  useEffect(() => { if (mode !== "autofill") return; const timer = window.setTimeout(() => setSuggestion(nextAutofillBlock(profile, accepted)), 800); return () => window.clearTimeout(timer); }, [accepted, editorText, mode, profile]);
  const acceptSuggestion = () => { if (!suggestion) return; const rendered = composeDraft(profile, "kerngleich"); const fullText = rendered.text; const blockIndex = rendered.blockIds.indexOf(suggestion.id); const nextIds = rendered.blockIds.slice(0, blockIndex + 1); const nextText = nextIds.map((id) => getBlock(id).text.replace(/\s+/g, " ").trim()).join(" "); setAccepted(nextIds); setEditorText(nextText); setSuggestion(null); };

