    {mode === "autofill" ? <div className="p-5"><div className="relative"><textarea value={editorText} onChange={(event) => setEditorText(event.target.value)} onKeyDown={(event) => { if (event.key === "Tab" && suggestion) { event.preventDefault(); acceptSuggestion(); } }} placeholder="Beginnen Sie zu schreiben – nach 800 ms erscheint der nächste geprüfte Baustein …" className="h-52 w-full resize-none rounded-xl border border-slate-200 bg-slate-950 p-5 font-mono text-sm leading-7 text-slate-100 outline-none focus:border-sky-500 focus:ring-2 focus:ring-sky-100" />{suggestion && <button type="button" onClick={acceptSuggestion} className="absolute bottom-4 left-4 right-4 flex items-start justify-between gap-3 rounded-lg border border-slate-700 bg-slate-900/95 p-3 text-left shadow-xl"><span><span className="block text-[10px] font-bold uppercase tracking-wider text-sky-400">Ghost-Text · {suggestion.id}</span><span className="mt-1 line-clamp-2 block font-mono text-xs leading-5 text-slate-400">{suggestion.text.replace(/\s+/g, " ")}</span></span><span className="flex shrink-0 items-center gap-1 rounded border border-slate-600 px-2 py-1 font-mono text-[10px] text-slate-300"><Keyboard className="size-3" /> Tab</span></button>}</div><p className="mt-2 text-[11px] text-slate-500">Keine freie Fortsetzung: angeboten wird ausschließlich der nächste Baustein aus <code>meta.segmentreihenfolge</code>.</p></div> : <div className="p-5"><div className="rounded-xl border border-slate-200 bg-[#fbfaf7] p-5 font-serif text-[17px] leading-8 text-slate-800 shadow-inner"><span className="select-none text-slate-400">I. </span>{draft.text}</div></div>}
    <SourceBar draft={mode === "autofill" ? { ...draft, blockIds: accepted, referenceIds: [...new Set(accepted.flatMap((id) => getBlock(id).belegt_in))] } : draft} />
