    <div className="max-h-[720px] space-y-3 overflow-auto p-3">{loading ? <div className="grid min-h-48 place-items-center text-center"><div><Loader2 className="mx-auto size-6 animate-spin text-sky-600" /><p className="mt-3 text-sm font-semibold">10 Regeln werden geprüft</p><p className="mt-1 text-xs text-slate-500">ohne Modellaufruf</p></div></div> : findings.length ? findings.map((item, index) => { const id = `${item.regel_id ?? "M"}-${index}`; const decision = decisions[id]; return <article key={id} className={`rounded-xl border p-3 ${item.schwere === "hoch" ? "border-red-200 bg-red-50/60" : item.schwere === "mittel" ? "border-amber-200 bg-amber-50/60" : "border-slate-200 bg-slate-50"}`}><div className="flex items-start justify-between gap-2"><div className="flex items-center gap-1.5"><span className={`size-2 rounded-full ${item.schwere === "hoch" ? "bg-red-500" : item.schwere === "mittel" ? "bg-amber-500" : "bg-slate-400"}`} /><span className="text-[10px] font-bold uppercase tracking-wider text-slate-600">{item.regel_id ?? "Modell"} · {item.typ.replace("_", " ")}</span></div><Chip variant={item.quelle === "regel" ? "blue" : "violet"}>{item.quelle}</Chip></div><p className="mt-2 text-xs font-semibold leading-5 text-slate-900">{item.begruendung}</p>{item.beispiel_nicht_erfasst && <div className="mt-2 rounded-md bg-white/80 p-2 text-[11px] leading-4 text-slate-600"><span className="font-bold">Rutscht durch:</span> {item.beispiel_nicht_erfasst}</div>}<div className="mt-2 flex flex-wrap gap-1">{item.referenz_ids.map((ref) => <Chip key={ref}>{ref}</Chip>)}{item.baustein_id && <Chip variant="green">→ {item.baustein_id}</Chip>}</div><div className="mt-3 flex gap-2"><button type="button" onClick={() => onDecision(id, "accepted")} className={`flex flex-1 items-center justify-center gap-1 rounded-md border px-2 py-1.5 text-[11px] font-semibold ${decision === "accepted" ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-200 bg-white text-slate-600"}`}><Check className="size-3" /> Übernehmen</button><button type="button" onClick={() => onDecision(id, "rejected")} className={`flex flex-1 items-center justify-center gap-1 rounded-md border px-2 py-1.5 text-[11px] font-semibold ${decision === "rejected" ? "border-slate-700 bg-slate-700 text-white" : "border-slate-200 bg-white text-slate-600"}`}><X className="size-3" /> Verwerfen</button></div></article>; }) : <div className="grid min-h-48 place-items-center text-center"><div><ShieldCheck className="mx-auto size-8 text-emerald-600" /><p className="mt-2 text-sm font-semibold">Noch keine Vollprüfung</p><p className="mt-1 max-w-48 text-xs leading-5 text-slate-500">Starten Sie rechts oben den deterministischen Prüfschritt 0.</p></div></div>}</div>
    <div className="border-t border-slate-100 px-4 py-3 text-[11px] text-slate-500">Annahmequote dieser Sitzung: <strong className="text-slate-800">{Object.keys(decisions).length ? Math.round((accepted / Object.keys(decisions).length) * 100) : 0} %</strong> · {Object.keys(decisions).length} Entscheidungen</div>
  </aside>;
