  return <div className="min-h-screen bg-[#f5f7f9] text-slate-900"><header className="border-b border-slate-200 bg-white/95 px-5 py-4 backdrop-blur"><div className="mx-auto flex max-w-[1540px] flex-wrap items-center justify-between gap-4"><div><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.18em] text-sky-700"><Scale className="size-4" /> Tenorschreibhilfe</div><h1 className="mt-1 font-sans text-2xl font-semibold tracking-tight">Komponieren. Begründen. Nachprüfen.</h1><p className="mt-1 text-xs text-slate-500">70 % geprüfte Formelbausteine · ein generatives Segment · jede Aussage mit ID</p></div><div className="flex flex-wrap items-center gap-2"><div className="flex rounded-lg border border-slate-200 bg-slate-50 p-1">{([['compose','Von null',Sparkles],['autofill','Autofill',Keyboard],['review','Vollprüfung',ClipboardCheck]] as const).map(([value,label,Icon]) => <button key={value} type="button" onClick={() => setMode(value)} className={`flex items-center gap-1.5 rounded-md px-3 py-2 text-xs font-semibold transition ${mode === value ? "bg-white text-slate-900 shadow-sm" : "text-slate-500"}`}><Icon className="size-3.5" />{label}</button>)}</div><button type="button" onClick={() => { setProfile(demoProfile); setWidth("eng"); setMode("compose"); setFindings([]); }} className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-50"><RotateCcw className="size-3.5" /> Demo laden</button><button type="button" onClick={runReview} className="flex items-center gap-1.5 rounded-lg bg-sky-600 px-4 py-2 text-xs font-bold text-white shadow-sm hover:bg-sky-700"><ClipboardCheck className="size-3.5" /> Vollprüfung starten</button></div></div></header>
    <main className="mx-auto max-w-[1540px] px-5 py-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-sky-100 bg-sky-50/70 px-4 py-3"><div className="flex items-center gap-2 text-xs text-sky-900"><Info className="size-4 text-sky-600" /><span><strong>Arbeitsentwurf.</strong> Alle 8 Fälle sind juristisch nicht freigegeben; nur T-001–T-004 sind am Volltext zitatgeprüft.</span></div><div className="flex gap-1.5"><Chip variant="blue">8 Tenore</Chip><Chip variant="blue">37 Bausteine</Chip><Chip variant="green">4 zitatgeprüft</Chip></div></div>
      <div className="grid items-start gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="space-y-4"><ProfileForm profile={profile} onChange={setProfile} />{mode !== "autofill" && <WidthChooser width={width} onChange={setWidth} drafts={drafts} />}<DraftEditor draft={draft} mode={mode} profile={profile} />{mode !== "autofill" && <ReviewOrder features={features} />}<SkyTimeline /></div><FindingsPanel findings={findings} loading={reviewing} decisions={decisions} onDecision={decide} /></div>
