  useEffect(() => { if (!autofill || sourceIds.length > 0) { setSuggestion(null); return; } const timer = window.setTimeout(() => setSuggestion(nextAutofillBlock(profile, sourceIds)), 800); return () => window.clearTimeout(timer); }, [autofill, profile, sourceIds, text]);

  const choose = (next: Exclude<Variant, null>, draft: Draft) => { setVariant(next); setText(draft.text); setSourceIds(draft.blockIds); setFindings(null); };
  const edit = (value: string) => { setText(value); setVariant(null); setSourceIds([]); setFindings(null); };
  const acceptSuggestion = () => { if (!suggestion) return; const phrase = suggestion.text.replace(/\s+/g, " ").trim(); setText((current) => `${current.trim()}${current.trim() ? " " : ""}${phrase}`); setSourceIds((current) => [...current, suggestion.id]); setSuggestion(null); };
  const review = () => { setReviewing(true); window.setTimeout(() => { setFindings(runDeterministicRules(profile, sourceIds, text)); setReviewing(false); }, 450); };
  const activeDraft = variant === "precise" ? precise : neutral;
  const features = deriveReviewFeatures(profile, activeDraft);

  return <section className="mt-8 rounded-[22px] border border-slate-200 bg-white shadow-[0_24px_70px_-42px_rgba(15,23,42,0.35)]">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-4 sm:px-7"><div><p className="text-sm font-semibold text-slate-950">Tenorentwurf</p><p className="mt-0.5 text-xs text-slate-400">Vorschlag wählen oder direkt bearbeiten</p></div><button type="button" onClick={() => setAutofill((value) => !value)} className={`flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-semibold ${autofill ? "border-blue-200 bg-blue-50 text-blue-700" : "border-slate-200 text-slate-500"}`}><Sparkles className="size-3.5" />Autofill {autofill ? "an" : "aus"}</button></div>
    <div className="p-5 sm:p-7"><div className="grid gap-3 md:grid-cols-2"><VariantCard selected={variant === "precise"} label="Präziser Entwurf" badge="konkret" description="Eng an der bekannten Verletzungsform. Gut vollstreckbar, aber kanalgebunden." draft={precise} onClick={() => choose("precise", precise)} /><VariantCard selected={variant === "neutral"} label="Technikneutraler Entwurf" badge="empfohlen" description="Erfasst Website und App, ohne sich an eine konkrete Domain zu binden." draft={neutral} onClick={() => choose("neutral", neutral)} /></div>
      <div className="relative mt-5"><textarea aria-label="Tenor bearbeiten" value={text} onChange={(event) => edit(event.target.value)} onKeyDown={(event) => { if (event.key === "Tab" && suggestion) { event.preventDefault(); acceptSuggestion(); } }} placeholder="Oder beginnen Sie hier direkt mit Ihrem Tenor …" className="min-h-[300px] w-full resize-y rounded-xl border border-slate-200 bg-white p-5 font-serif text-[17px] leading-8 text-slate-800 outline-none transition placeholder:font-sans placeholder:text-sm placeholder:text-slate-300 focus:border-blue-400 focus:ring-4 focus:ring-blue-50" />{suggestion && <button type="button" onClick={acceptSuggestion} className="absolute bottom-4 left-4 right-4 flex items-start justify-between gap-4 rounded-lg border border-blue-100 bg-blue-50/95 p-3 text-left shadow-sm"><span><span className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-blue-700"><Sparkles className="size-3" />Vorschlag {suggestion.id}</span><span className="mt-1 line-clamp-2 block text-xs leading-5 text-slate-600">{suggestion.text.replace(/\s+/g, " ")}</span></span><span className="flex shrink-0 items-center gap-1 rounded border border-blue-200 bg-white px-2 py-1 font-mono text-[10px] text-blue-700"><Keyboard className="size-3" />Tab</span></button>}</div>
      <div className="mt-3 flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap items-center gap-1.5"><span className="mr-1 text-[10px] font-semibold uppercase tracking-wider text-slate-400">Quellen</span>{sourceIds.length ? sourceIds.map((id) => { const block = getBlock(id); const refs = block.belegt_in.length ? block.belegt_in.map(referenceLabel).join("/") : "T-001 · Entscheidungsgründe"; return <SourcePill key={id}>{id} · {refs}</SourcePill>; }) : <span className="text-[11px] text-amber-600">Eigenformulierung – noch ohne Bausteinbeleg</span>}</div><button type="button" onClick={review} disabled={reviewing} className="flex items-center gap-2 rounded-lg bg-slate-950 px-4 py-2.5 text-xs font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60">{reviewing ? <Loader2 className="size-3.5 animate-spin" /> : <ShieldCheck className="size-3.5" />}Tenor prüfen</button></div>
      {findings && <ReviewDetails findings={findings} features={features} />}
      <details className="mt-4 border-t border-slate-100 pt-4 text-xs text-slate-500"><summary className="flex cursor-pointer list-none items-center gap-1.5 font-semibold text-slate-500"><ChevronDown className="size-3.5" />Hinweise zu Quellen und Freigabe</summary><p className="mt-2 max-w-3xl leading-5">Jeder Systemvorschlag trägt Baustein- und Referenz-IDs. Die acht Referenzfälle sind noch nicht juristisch freigegeben; nur T-001 bis T-004 wurden am Volltext geprüft. Das System schlägt vor und begründet. Die Freigabe bleibt menschlich.</p></details>
    </div>
  </section>;
}

