  fallgruppe: "kuendigungsbutton", verstossModus: "vorhanden_unzureichend",
  rechtsgrundlage: ["§ 2 Abs. 1 UKlaG", "§ 312k Abs. 2 BGB", "§ 890 ZPO"], beanstandeterWortlaut: "",
  wirkung: "Die Kündigungsschaltfläche wird erst nach dem Aufklappen weiterer Links sichtbar.",
  bekannteUmgehungen: ["Verlagerung in die App", "Zwei-Button-Lösung"],
  gestaltungsmerkmale: ["versteckte Schaltfläche", "zusätzliche Interaktion"], anlage: "K 1",
};

type EntryMode = "pdf" | "form" | null;
type Variant = "precise" | "neutral" | null;

function referenceLabel(referenceId: string) {
  const reference = register.tenore.find((item) => item.id === referenceId);
  return reference?.zitat_geprueft === true ? referenceId : `${referenceId} · ungeprüft`;
}

function SourcePill({ children, accent = false }: { children: ReactNode; accent?: boolean }) {
  return <span className={`inline-flex rounded-full border px-2.5 py-1 font-mono text-[10px] font-semibold ${accent ? "border-blue-200 bg-blue-50 text-blue-700" : "border-slate-200 bg-white text-slate-500"}`}>{children}</span>;
}

function EntryChoice({ mode, onSelect }: { mode: EntryMode; onSelect: (mode: Exclude<EntryMode, null>) => void }) {
  const choices = [
    { value: "pdf" as const, label: "PDF hochladen", description: "Urteil oder Abmahnung verwenden", icon: Upload },
    { value: "form" as const, label: "Kurze Maske", description: "Nur die wichtigsten Angaben", icon: PencilLine },
  ];
  return <section aria-labelledby="start-heading">
    <div className="text-center"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-blue-600">Tenorschreibhilfe</p><h1 id="start-heading" className="mt-2 font-sans text-3xl font-semibold tracking-tight text-slate-950 sm:text-4xl">Wie möchten Sie beginnen?</h1><p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-slate-500">Dokument hochladen, vier Angaben machen – oder direkt unten losschreiben.</p></div>
    <div className="mx-auto mt-7 grid max-w-2xl gap-3 sm:grid-cols-2">{choices.map((choice) => { const active = mode === choice.value; return <button key={choice.value} type="button" onClick={() => onSelect(choice.value)} className={`flex items-center gap-4 rounded-2xl border p-4 text-left transition ${active ? "border-blue-500 bg-blue-50 shadow-sm ring-4 ring-blue-50" : "border-slate-200 bg-white hover:border-slate-300 hover:shadow-sm"}`}><span className={`grid size-11 shrink-0 place-items-center rounded-xl ${active ? "bg-blue-600 text-white" : "bg-slate-100 text-slate-600"}`}><choice.icon className="size-5" /></span><span><span className="block text-sm font-semibold text-slate-900">{choice.label}</span><span className="mt-1 block text-xs text-slate-500">{choice.description}</span></span>{active && <Check className="ml-auto size-5 text-blue-600" />}</button>; })}</div>
  </section>;
}

function PdfInput({ file, onFile }: { file: File | null; onFile: (file: File | null) => void }) {
  const inputRef = useRef<HTMLInputElement>(null);
  const accept = (candidate?: File) => { if (candidate && (candidate.type === "application/pdf" || candidate.name.toLowerCase().endsWith(".pdf"))) onFile(candidate); };
  return <div className="mx-auto mt-4 max-w-2xl">{file ? <div className="flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3"><span className="grid size-9 place-items-center rounded-lg bg-white text-emerald-700"><FileText className="size-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-slate-900">{file.name}</p><p className="mt-0.5 text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(1)} MB · bleibt lokal</p></div><button type="button" onClick={() => onFile(null)} aria-label="PDF entfernen" className="rounded-full p-2 text-slate-400 hover:bg-white hover:text-slate-700"><X className="size-4" /></button></div> : <button type="button" onClick={() => inputRef.current?.click()} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); accept(event.dataTransfer.files[0]); }} className="flex w-full items-center justify-center gap-3 rounded-xl border border-dashed border-slate-300 bg-white px-5 py-5 text-sm text-slate-600 transition hover:border-blue-400 hover:bg-blue-50/30"><Upload className="size-4 text-blue-600" /><span><strong className="text-slate-900">PDF auswählen</strong> oder hier ablegen</span></button>}
    <input ref={inputRef} type="file" accept="application/pdf,.pdf" className="hidden" onChange={(event) => accept(event.target.files?.[0])} />
    {file && <p className="mt-2 flex items-start gap-1.5 text-[11px] leading-4 text-slate-400"><Info className="mt-0.5 size-3 shrink-0" />Die Datei wird in dieser lokalen Demo nicht übertragen. Die automatische PDF-Texterkennung ist noch nicht angeschlossen; der Entwurf bleibt bis dahin mit Beispielangaben vorbelegt.</p>}</div>;
