function ShortForm({ profile, onChange }: { profile: Profile; onChange: (profile: Profile) => void }) {
  const inputClass = "h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm text-slate-800 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100";
  return <div className="mx-auto mt-4 grid max-w-2xl gap-3 rounded-2xl border border-slate-200 bg-white p-4 sm:grid-cols-2">
    <label className="space-y-1.5 text-xs font-semibold text-slate-600">Worum geht es?<select value={profile.fallgruppe} onChange={(event) => { const fallgruppe = event.target.value; const verstossModus = fallgruppe === "agb_klausel" ? "klausel_verwendet" : fallgruppe === "kuendigungsbutton" ? "vorhanden_unzureichend" : "irrefuehrend_gestaltet"; onChange({ ...profile, fallgruppe, verstossModus }); }} className={inputClass}><option value="kuendigungsbutton">Kündigungsbutton</option><option value="agb_klausel">AGB-Klausel</option><option value="dark_pattern_dsa">Dark Pattern</option><option value="consent_gestaltung">Cookie-Banner</option><option value="irrefuehrende_werbung">Irreführende Werbung</option></select></label>
    <label className="space-y-1.5 text-xs font-semibold text-slate-600">Was ist das Problem?<select value={profile.verstossModus} onChange={(event) => onChange({ ...profile, verstossModus: event.target.value })} className={inputClass}><option value="vorhanden_unzureichend">vorhanden, aber unzureichend</option><option value="fehlt_vollstaendig">fehlt vollständig</option><option value="irrefuehrend_gestaltet">irreführend gestaltet</option><option value="klausel_verwendet">Klausel verwendet</option></select></label>
    <label className="space-y-1.5 text-xs font-semibold text-slate-600">Webseite oder Fundstelle<input value={profile.url} onChange={(event) => onChange({ ...profile, url: event.target.value })} className={inputClass} /></label>
    <fieldset className="space-y-1.5"><legend className="text-xs font-semibold text-slate-600">Wo tritt es auf?</legend><div className="flex h-10 items-center gap-2">{([["website", "Website"], ["app", "App"]] as const).map(([value, label]) => { const active = profile.kanal.includes(value); return <button key={value} type="button" onClick={() => onChange({ ...profile, kanal: active ? profile.kanal.filter((item) => item !== value) : [...profile.kanal, value] })} className={`h-10 flex-1 rounded-lg border text-xs font-semibold ${active ? "border-blue-500 bg-blue-50 text-blue-700" : "border-slate-200 bg-white text-slate-500"}`}>{label}</button>; })}</div></fieldset>
  </div>;
}

function VariantCard({ selected, label, badge, description, draft, onClick }: { selected: boolean; label: string; badge: string; description: string; draft: Draft; onClick: () => void }) {
  return <button type="button" onClick={onClick} className={`rounded-xl border p-4 text-left transition ${selected ? "border-blue-500 bg-blue-50/60 ring-2 ring-blue-100" : "border-slate-200 bg-white hover:border-slate-300"}`}><div className="flex items-center justify-between gap-2"><span className="flex items-center gap-2 text-sm font-semibold text-slate-900"><span className={`grid size-4 place-items-center rounded-full border ${selected ? "border-blue-600 bg-blue-600" : "border-slate-300"}`}>{selected && <span className="size-1.5 rounded-full bg-white" />}</span>{label}</span><span className="rounded-full bg-white px-2 py-1 text-[10px] font-semibold text-slate-500">{badge}</span></div><p className="mt-2 text-xs leading-5 text-slate-500">{description}</p><p className="mt-3 line-clamp-2 font-serif text-sm leading-6 text-slate-700">{draft.text}</p></button>;
}

function ReviewDetails({ findings, features }: { findings: Finding[]; features: ReturnType<typeof deriveReviewFeatures> }) {
  return <div className="mt-5 grid gap-3 border-t border-slate-100 pt-5 md:grid-cols-2">
    <div className="rounded-xl bg-slate-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-wider text-slate-500">Prüfbefunde</p><SourcePill accent>{findings.length}</SourcePill></div>{findings.length ? <ul className="mt-3 space-y-2">{findings.map((finding, index) => <li key={`${finding.regel_id}-${index}`} className="rounded-lg border border-slate-200 bg-white p-3"><p className="text-xs font-semibold text-slate-800">{finding.regel_id ?? "Modell"} · {finding.typ.replace("_", " ")}</p><p className="mt-1 text-[11px] leading-4 text-slate-500">{finding.begruendung}</p></li>)}</ul> : <p className="mt-3 text-xs text-slate-500">Keine deterministischen Befunde.</p>}</div>
    <div className="rounded-xl bg-slate-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-wider text-slate-500">Prüfauftrag</p><SourcePill accent>{features.length}</SourcePill></div><ul className="mt-3 space-y-2">{features.slice(0, 4).map((feature) => <li key={feature.merkmal} className="flex gap-2 text-xs leading-4 text-slate-600"><span className={`mt-0.5 grid size-4 shrink-0 place-items-center rounded-full ${feature.automatisierbar ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}>{feature.automatisierbar ? <Check className="size-2.5" /> : "M"}</span>{feature.merkmal}</li>)}</ul></div>
  </div>;
}

function WritingArea({ profile }: { profile: Profile }) {
  const precise = useMemo(() => composeDraft(profile, "eng"), [profile]);
  const neutral = useMemo(() => composeDraft(profile, "kerngleich"), [profile]);
  const [variant, setVariant] = useState<Variant>("neutral");
  const [text, setText] = useState(neutral.text);
  const [sourceIds, setSourceIds] = useState(neutral.blockIds);
  const [suggestion, setSuggestion] = useState<ReturnType<typeof nextAutofillBlock>>(null);
  const [autofill, setAutofill] = useState(true);
  const [reviewing, setReviewing] = useState(false);
  const [findings, setFindings] = useState<Finding[] | null>(null);

  useEffect(() => { if (variant === "precise") { setText(precise.text); setSourceIds(precise.blockIds); } if (variant === "neutral") { setText(neutral.text); setSourceIds(neutral.blockIds); } }, [neutral, precise, variant]);
  useEffect(() => { if (!autofill || sourceIds.length > 0) { setSuggestion(null); return; } const timer = window.setTimeout(() => setSuggestion(nextAutofillBlock(profile, sourceIds)), 800); return () => window.clearTimeout(timer); }, [autofill, profile, sourceIds, text]);

